/* eslint-disable @typescript-eslint/no-unused-expressions */

import extract = require( './index' );

// TESTS //

// The function returns an array of blocks...
{
	extract( 'path/to/file.c' ); // $ExpectType Block[]
	extract( 'path/to/file.c', 'src' ); // $ExpectType Block[]
	extract( 'path/to/file.md', 'markdown' ); // $ExpectType Block[]
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	extract( 123 ); // $ExpectError
	extract( true ); // $ExpectError
	extract( false ); // $ExpectError
	extract( null ); // $ExpectError
	extract( undefined ); // $ExpectError
	extract( [] ); // $ExpectError
	extract( {} ); // $ExpectError
	extract( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an allowed string...
{
	extract( 'path/to/file.c', 123 ); // $ExpectError
	extract( 'path/to/file.c', true ); // $ExpectError
	extract( 'path/to/file.c', false ); // $ExpectError
	extract( 'path/to/file.c', null ); // $ExpectError
	extract( 'path/to/file.c', [] ); // $ExpectError
	extract( 'path/to/file.c', {} ); // $ExpectError
	extract( 'path/to/file.c', ( x: number ): number => x ); // $ExpectError
	extract( 'path/to/file.c', 'invalid_mode' ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	extract(); // $ExpectError
	extract( 'path/to/file.c', 'src', 1 ); // $ExpectError
}
